local config = {
  ui_story_30960401_1_dialog_content = "Halo.",
  ui_story_30960401_2_dialog_content = "Halo, Sariel. Ada yang bisa kuban—",
  ui_story_30960401_3_dialog_content = "Berdiri sedikit ke kiri.",
  ui_story_30960401_4_dialog_content = "Apa?",
  ui_story_30960401_5_dialog_content = "Ambil satu langkah ke kiri... Posisimu kurang tengah dari dinding di belakangmu.",
  ui_story_30960401_6_dialog_content = "...?",
  ui_story_30960401_7_dialog_content = "*Melangkah ke kiri*",
  ui_story_30960401_8_dialog_content = "Hmm... Jauh lebih baik.",
  ui_story_30960401_9_dialog_content = "Jadi, <color=#FFB400>Gabriel</color>...",
  ui_story_30960401_10_dialog_content = "Namaku PlayerName...",
  ui_story_30960401_11_dialog_content = "Aku tahu. Aku hanya ingin tanya apa kau tahu di mana Gabriel.",
  ui_story_30960401_12_dialog_content = "Kau memanggilku ke sini, tapi kau sebenarnya mencari orang lain...",
  ui_story_30960401_13_dialog_content = "Kau bisa bertanya padaku lewat terminal saja...",
  ui_story_30960401_14_dialog_content = "Aku lupa.",
  ui_story_30960401_15_dialog_content = "...",
  ui_story_30960401_16_option_content = "Aku memberi Gabriel tugas.",
  ui_story_30960401_17_dialog_content = "Hmm... Begitukah...?",
  ui_story_30960401_18_dialog_content = "Kau tampak kecewa... Ada masalah?",
  ui_story_30960401_19_dialog_content = "Kapan dia akan kembali?",
  ui_story_30960401_20_dialog_content = "Kalau tidak mencuri waktu untuk tidur siang, dia seharusnya kembali dalam sekitar enam jam.",
  ui_story_30960401_21_dialog_content = "Bukan begitu cara menaikkan semangat karyawan...",
  ui_story_30960401_22_dialog_content = "Aku dengar, Sariel...",
  ui_story_30960401_23_option_content = "Gabriel belum bergabung.",
  ui_story_30960401_24_dialog_content = "Maaf, tapi Gabriel belum jadi anggota timku. Maksudmu Angel of Lumopolis, 'kan...?",
  ui_story_30960401_25_dialog_content = "Sayang sekali.",
  ui_story_30960401_26_dialog_content = "Oh, tidak. Maksudku... Kau ada untuk membantuku, 'kan?",
  ui_story_30960401_27_dialog_content = "Maksudku, sayang sekali untukku...",
  ui_story_30960401_28_dialog_content = "Aku datang ke sini hanya karena kudengar ada banyak Aurorian dari Lumopolis denganmu.",
  ui_story_30960401_29_dialog_content = "Kenapa sikapmu jadi begini?",
  ui_story_30960401_30_dialog_content = "Lupakan. Intinya—",
  ui_story_30960401_31_dialog_content = "Kau punya uang tunai?",
  ui_story_30960401_32_dialog_content = "Wow... Apa pula ini!? Tunggu... Kau sebenarnya ingin apa?",
  ui_story_30960401_33_dialog_content = "Pinjami aku uang. Itu saja.",
  ui_story_30960401_34_dialog_content = "\"Itu saja\"!? Sepertinya kau sudah memutuskan bahwa aku akan memberimu uang...",
  ui_story_30960401_35_dialog_content = "Ini sungguh mendesak... Aku tidak bisa menjelaskan alasannya, tapi aku butuh uang.",
  ui_story_30960401_36_dialog_content = "Aku mengerti... Tapi kau bekerja sampai larut setiap hari, 'kan? Seharusnya kau punya banyak uang sekarang...",
  ui_story_30960401_37_dialog_content = "Semua hilang.",
  ui_story_30960401_38_dialog_content = "Karena... penghancuran tidak terkontrol dan \"luka yang tidak disengaja\".",
  ui_story_30960401_39_dialog_content = "Bagaimana bisa kau mengatakan sesuatu yang aneh, tapi sangat tenang...",
  ui_story_30960401_40_dialog_content = "Berapa banyak uang yang kau butuhkan? Aku akan bicara kepada Vice. Seharusnya tidak terlalu—",
  ui_story_30960401_41_dialog_content = "<color=#FFB400>23.967.500</color> Nightium.",
  ui_story_30960401_42_dialog_content = "...",
  ui_story_30960401_43_dialog_content = "Ha... Sejenak aku pikir kau bilang 20 juta lebih... Haha... Tunggu, berapa banyak!?",
  ui_story_30960401_44_dialog_content = "Benar, <color=#FFB400><size=45>23.967.500 Nightium</size></color>.",
  ui_story_30960401_45_dialog_content = "...",
  ui_story_30960401_46_dialog_content = "...",
  ui_story_30960401_47_dialog_content = "Sariel, kau ada masalah apa?",
  ui_story_30960401_48_dialog_content = "Tidak.",
  ui_story_30960401_49_dialog_content = "Kau bercanda? Apa seseorang memintamu melakukan ini?",
  ui_story_30960401_50_dialog_content = "Tidak...",
  ui_story_30960401_51_dialog_content = "Apa Kleken memintamu datang ke sini?",
  ui_story_30960401_52_dialog_content = "PlayerName, jujur aku hanya meminta bantuanmu.",
  ui_story_30960401_53_dialog_content = "Kalau begitu, sebaiknya kau jelaskan alasanmu butuh uang sebanyak itu.",
  ui_story_30960401_54_dialog_content = "Kau tahu, mungkin kalau aku menjual kepala Jona, aku mungkin bisa mendapatkan sejumlah uang itu untukmu.",
  ui_story_30960401_55_dialog_content = "Aku butuh uang untuk membeli tiket.",
  ui_story_30960401_56_dialog_content = "Hanya satu tiket... Sangat penting untukku.",
  ui_story_30960401_57_dialog_content = "Hmm... Apa itu tiket satu arah ke \"The Land of Infinite Wealth and Freedom\"?",
  ui_story_30960401_58_dialog_content = "<size=40>Di mana itu?</size> <size=45>Aku ingin berkunjung.</size> <size=50>Kalau aku ke sana, apa aku akan jadi kaya... dan merdeka?</size>",
  ui_story_30960401_59_dialog_content = "Maaf... Aku lupa kau selalu mengartikan kata-kata orang secara harfiah...",
  ui_story_30960401_60_dialog_content = "Maksudku tadi tiket pesawat ke Lumopolis.",
  ui_story_30960401_61_dialog_content = "Tiket pesawat? Dan harganya lebih dari 20 juta?",
  ui_story_30960401_62_dialog_content = "Ya. Pesawat penumpang yang melayani rute Umbraton-Lumopolis setiap hari.",
  ui_story_30960401_63_dialog_content = "Kau bilang setiap tiket harganya lebih dari 20 juta? Kata siapa itu?",
  ui_story_30960401_64_dialog_content = "Kleken.",
  ui_story_30960401_65_dialog_content = "(Aku tahu dia pasti terlibat dengan ini...)",
  ui_story_30960401_66_dialog_content = "Aku hitung kalau terus bekerja di Umbraton, aku perlu sekitar... <color=#FFB400>3.000</color> tahun untuk mendapatkan uang sebanyak itu.",
  ui_story_30960401_67_dialog_content = "Hmm... Atau <color=#FFB400>30.000</color> tahun, ya? Aku tidak ingat. Ah, dan angka 3-nya sangat tidak jelas... Kita ubah jadi 8 saja...",
  ui_story_30960401_68_dialog_content = "Sariel, aku teringat peribahasa tertentu... Tapi, aku tidak yakin apa aku harus mengatakannya.",
  ui_story_30960401_69_dialog_content = "Aku juga tidak tahu... karena aku belum mendengarnya.",
  ui_story_30960401_70_dialog_content = "Menurutmu, bukannya harga itu sangat tidak masuk akal? Apa mungkin orang mampu membeli tiket semahal itu?",
  ui_story_30960401_71_dialog_content = "...",
  ui_story_30960401_72_dialog_content = "Oh!",
  ui_story_30960401_73_dialog_content = "Jadi, begitu!",
  ui_story_30960401_74_dialog_content = "(Mungkinkah... akhirnya dia paham?)",
  ui_story_30960401_75_dialog_content = "Penumpang yang lain pasti sudah bekerja <size=45>sangat keras, 'kan</size>?",
  ui_story_30960401_76_dialog_content = "Eh... Mereka pasti sudah bekerja <size=45>sangat lama, 'kan</size>?",
  ui_story_30960401_77_dialog_content = "Maaf, aku terus lupa bahwa kau... agak lemah dalam hal akal sehat.",
  ui_story_30960401_78_dialog_content = "Sepertinya kau mengejekku. Aku cukup mengenal raut wajah begitu.",
  ui_story_30960401_79_dialog_content = "M-maaf... Tapi kau sangat berbeda dari kebanyakan orang yang pernah kutemui, Sariel.",
  ui_story_30960401_80_dialog_content = "Benarkah? Apa maksudmu?",
  ui_story_30960401_81_dialog_content = "Tunggu sebentar. Geser sedikit ke kiri terlebih dulu.",
  ui_story_30960401_82_dialog_content = "??",
  ui_story_30960401_83_dialog_content = "Kau baru saja bergerak dari titik tengah dinding. Sekarang sudah bagus. Kau kembali simetris.",
  ui_story_30960401_84_dialog_content = "Jadi? Apa bedanya antara aku dan yang lain?",
  ui_story_30960401_85_dialog_content = "...",
  ui_story_30960401_86_dialog_content = "Sariel, coba aku menebak sesuatu terlebih dulu. Katakan apakah aku benar:",
  ui_story_30960401_87_dialog_content = "Kau pergi ke Lumopolis itu ada kaitannya dengan Gabriel, 'kan?",
  ui_story_30960401_88_dialog_content = "...",
  ui_story_30960401_89_dialog_content = "(Tebakanku benar?)",
  ui_story_30960401_90_dialog_content = "Kau... menggunakan kemampuan supranaturalmu?",
  ui_story_30960401_91_dialog_content = "Tidak... Itu sudah jelas.",
  ui_story_30960401_92_dialog_content = "Kenapa kau mencarinya? Mungkin aku bisa bantu? Maksudku, selain memberikan 20 juta tadi...",
  ui_story_30960401_93_dialog_content = "Ini tentang kakekku.",
  ui_story_30960401_94_dialog_content = "Kakek?",
  ui_story_30960401_95_dialog_content = "Ya. Aku ingin bertanya kepada Gabriel bagaimana dia meninggal.",
  ui_story_30960401_96_dialog_content = "Oh... Itu... Aku mengerti...",
  ui_story_30960401_97_dialog_content = "Dua belas tahun lalu. Bukan, sepuluh tahun lalu? Kita rata-rata saja, sebelas tahun yang lalu.",
  ui_story_30960401_98_dialog_content = "Kakekku, <color=#FFB400>Amos</color>, meninggal di Lumopolis.",
  ui_story_30960401_99_dialog_content = "Aku masih kecil saat itu, dan sebagian besar ingatanku tentangnya kabur, tapi aku ingat jelas satu hal.",
  ui_story_30960401_100_dialog_content = "Suatu hari, kakekku tiba-tiba melakukan perjalanan panjang. Dia memintaku tinggal di rumah, dan bilang akan segera kembali.",
  ui_story_30960401_101_dialog_content = "Aku mendengar sebuah nama saat itu—Gabriel. Dia adalah alasan kakekku harus meninggalkan rumah dan pergi ke Lumopolis.",
  ui_story_30960401_102_dialog_content = "Aku tidak tahu itu adalah saat terakhir aku melihatnya.",
  ui_story_30960401_103_dialog_content = "Aku tidak tahu itu... \"Jadilah gadis yang baik, Sariel,\" adalah kata-kata terakhirnya untukku.",
  ui_story_30960401_104_option_content = "Maaf aku sudah mengingatkanmu...",
  ui_story_30960401_105_dialog_content = "Terima kasih atas pengertianmu, PlayerName... Tapi kau tidak harus minta maaf.",
  ui_story_30960401_106_dialog_content = "Aku selalu ingat hari itu. Tidak akan pernah lupa.",
  ui_story_30960401_107_dialog_content = "Hari itu juga meninggalkan pertanyaan yang terus terngiang di kepalaku—siapa Gabriel?",
  ui_story_30960401_108_option_content = "Aku memahami kesedihanmu.",
  ui_story_30960401_109_dialog_content = "Bisa dibilang, kau dan aku mencari sesuatu yang cukup mirip.",
  ui_story_30960401_110_dialog_content = "Kunci ingatanku adalah Gabriel, gadis yang belum pernah aku temui.",
  ui_story_30960401_111_dialog_content = "Angel of Lumopolis, Member of the Guardians, Girl in the Bird Cage...",
  ui_story_30960401_112_dialog_content = "Cerita dan rumor tidak menjawab pertanyaanku, jadi aku harus pergi mencari tahu sendiri.",
  ui_story_30960401_113_dialog_content = "Aku harus bertemu dia sendiri dan bertanya apa yang terjadi bertahun-tahun lalu. Aku harus tahu apa yang terjadi pada kakekku, Amos.",
  ui_story_30960401_114_dialog_content = "Dan aku perlu tahu... siapa dia sebenarnya.",
  ui_story_30960401_115_dialog_content = "Sejauh yang kutahu, masa lalu Gabriel benar-benar tidak terkesan serumit itu... Tapi tentu saja, aku tidak tahu cerita lengkapnya.",
  ui_story_30960401_116_dialog_content = "Apa? Tapi dia pasti tahu sesuatu, 'kan?",
  ui_story_30960401_117_dialog_content = "Di Lumopolis, di pulau apung itu... Mungkin di sana aku akan menemukan jawaban yang kucari.",
  ui_story_30960401_118_dialog_content = "...",
  ui_story_30960401_119_dialog_content = "Ah, aku tahu kakekku meninggal di Lumopolis Hospital.",
  ui_story_30960401_120_dialog_content = "Luka parah membuatnya koma, dan tidak pernah bangun lagi.",
  ui_story_30960401_121_dialog_content = "Apa dia mengalami kecelakaan? Dan Gabriel terlibat?",
  ui_story_30960401_122_dialog_content = "Bahkan Shadowlord tidak tahu lebih dari itu, jadi aku harus pergi dan mencari tahu sendiri.",
  ui_story_30960401_123_dialog_content = "Bagaimanapun, itulah alasan aku harus mencari Gabriel.",
  ui_story_30960401_124_dialog_content = "(Aku punya firasat bahwa Shadowlord yang \"serba tahu\" ini menyembunyikan sesuatu...)",
  ui_story_30960401_125_dialog_content = "(Lalu ada Kleken...)",
  ui_story_30960401_127_dialog_content = "Dia tidak punya kontrol sedikit pun atas kekuatannya sendiri. Kau tahu itu, 'kan?",
  ui_story_30960401_128_dialog_content = "Dengan dua kepribadiannya yang labil, Sariel harus berada di bawah pengawasan Shadowlord sepanjang waktu, demi keamanan.",
  ui_story_30960401_130_dialog_content = "Atau mungkin—di bawah pengawasanmu, PlayerName?",
  ui_story_30960401_131_dialog_content = "Kau punya banyak beban, PlayerName... dan jalanmu masih panjang.",
  ui_story_30960401_133_dialog_content = "Semuanya hilang...",
  ui_story_30960401_134_dialog_content = "Karena... penghancuran tidak terkontrol dan \"luka yang tidak disengaja\".",
  ui_story_30960401_136_dialog_content = "(Itulah yang pasti dipikirkan orang itu.)",
  ui_story_30960401_137_dialog_content = "Jadi...",
  ui_story_30960401_138_dialog_content = "Kau mengagetkanku.",
  ui_story_30960401_139_dialog_content = "Bisa kau bantu aku?",
  ui_story_30960401_140_dialog_content = "Tentu saja! Kau temanku, 'kan? Masalahmu adalah masalahku.",
  ui_story_30960401_141_dialog_content = "Hmm...",
  ui_story_30960401_142_dialog_content = "Namun... Aku tidak punya cukup uang, dan uang yang aku punya dibawa Vice. Tiap pengeluaran harus dipertanggungjawabkan.",
  ui_story_30960401_143_dialog_content = "Aku mengerti. Di mana Vice?",
  ui_story_30960401_144_dialog_content = "Tidak, tidak, tidak! Bukan itu maksudku... Sariel, aku bisa membantumu mencari Gabriel.",
  ui_story_30960401_145_dialog_content = "Oh! Itu juga bagus!",
  ui_story_30960401_146_dialog_content = "Bukankah ini semua tentang itu!? Kau lupa!?",
  ui_story_30960401_147_dialog_content = "Kapan? Aku bisa menunggu di sini.",
  ui_story_30960401_148_dialog_content = "Berapa pun waktu yang diperlukan, aku bisa menunggu. Ah, tidak... Sebenarnya, aku harus kembali ke Umbraton untuk mendaftar masuk...",
  ui_story_30960401_149_dialog_content = "Kalau aku mendaftar masuk pukul 8.00 pagi, lalu lagi pukul 8.00 malam, angkanya akan persis cocok...",
  ui_story_30960401_150_dialog_content = "Tunggu... Kalau mereka menggunakan format 24 jam, berarti pukul 8.00 dan 20.00, 'kan?",
  ui_story_30960401_151_dialog_content = "Tunggu! Aku akan segera kembali!",
  ui_story_30960401_152_dialog_content = "S-Sariel!?",
  ui_story_30960401_153_dialog_content = "Dia sudah pergi...",
  ui_story_30960401_154_dialog_content = "Amos... Nama kakek Sariel.",
  ui_story_30960401_155_dialog_content = "Sulit dibayangkan Gabriel terlibat dalam misteri jahat seperti itu...",
  ui_story_30960401_156_dialog_content = "...",
  ui_story_30960401_157_dialog_content = "Apa yang sebenarnya terjadi sepuluh tahun lalu...",
  ui_story_30960601_1_dialog_content = "Cuaca hari ini cerah...",
  ui_story_30960601_2_dialog_content = "<color=#e8d9bb>Srek!</color>",
  ui_story_30960601_3_dialog_content = "D-dari mana kertas ini berasal?! Tahu-tahu mengenai wajahku...",
  ui_story_30960601_4_dialog_content = "Hmm? Ada tulisannya...",
  ui_story_30960601_5_dialog_content = "\"Apa kamu ingin jadi orang yang lebih baik? Apa kamu ingin jadi orang sukses?\"",
  ui_story_30960601_6_dialog_content = "\"Kalau begitu, datanglah ke Rising Star Agency dan mendaftarlah hari ini!\"",
  ui_story_30960601_7_dialog_content = "\"Kami akan memuaskan hasratmu untuk jadi orang hebat dengan bermacam-macam pelajaran dan gaya pengajaran!\"",
  ui_story_30960601_8_dialog_content = "\"Biaya pelajaran mulai dari 1.998 Nightium. Instruktur akan datang ke rumahmu untuk mengajarkannya!\"",
  ui_story_30960601_9_dialog_content = "\"Mulai sekarang, kamu juga bisa mengubah seluruh hidupmu dan menjadikannya lebih baik!\"",
  ui_story_30960601_10_dialog_content = "Kedengarannya menarik.",
  ui_story_30960601_11_dialog_content = "Permisi, bolehkah aku masuk?",
  ui_story_30960601_12_dialog_content = "Tentu saja.",
  ui_story_30960601_13_dialog_content = "Halo, aku <color=#FFB400>instruktur</color> yang ditugaskan oleh Rising Star Agency. Apa kabar?",
  ui_story_30960601_17_dialog_content = "S-Sariel?! Kenapa kamu...?",
  ui_story_30960601_18_dialog_content = "*Batuk-batuk* Anu, aku... bekerja untuk Rising Star Agency saat ini.",
  ui_story_30960601_19_dialog_content = "Kuberi tahu, ya... Bonus dari pekerjaan ini sangat besar!",
  ui_story_30960601_20_dialog_content = "Mereka bahkan memberiku pakaian!",
  ui_story_30960601_21_dialog_content = "Baguslah, tapi... Kenapa kamu memberitahuku?",
  ui_story_30960601_22_dialog_content = "Yah, kami dilarang membagikan informasi ini dengan orang lain... Tapi, kita kan berteman dekat, jadi aku ingin memberitahumu.",
  ui_story_30960601_23_dialog_content = "Ini juga pertama kalinya aku mengajar, jadi maafkan aku kalau ada kesalahan di sana-sini.",
  ui_story_30960601_23X_dialog_content = "Tentu saja, aku mengerti.",
  ui_story_30960601_24_dialog_content = "Ehem... Tanpa perlu berlama-lama lagi, ayo kita mulai.",
  ui_story_30960601_25_dialog_content = "Pelajaran yang kamu pilih adalah: \"Cara Menghindari Konflik dengan Orang Lain\", \"Teknik Rahasia: Memimpin\", dan \"Cara Mencapai Kekayaan\".",
  ui_story_30960601_26_dialog_content = "Kita mulai pelajaran pertama: \"Cara Menghindari Konflik dengan Orang Lain\".",
  ui_story_30960601_27_dialog_content = "Sebelum kita mulai, aku ingin mengajukan sedikit pertanyaan...",
  ui_story_30960601_28_dialog_content = "Jika ada orang yang memintamu bergabung dengan timnya, tapi sebenarnya kamu tidak begitu ingin, bagaimana caramu menjawabnya?",
  ui_story_30960601_29_dialog_content = "Memangnya apa hubungannya itu dengan konflik?",
  ui_story_30960601_30_dialog_content = "Anu, aku hanya ingin lebih memahami kepribadianmu sehingga kita bisa menentukan metode komunikasi yang positif.",
  ui_story_30960601_31_dialog_content = "Kalau begitu, apa jawabanmu?",
  ui_story_30960601_32_dialog_content = "A: Berterima kasih atas ajakannya yang ramah, dan menolak dengan sopan.",
  ui_story_30960601_33_dialog_content = "B: Menolaknya dengan kasar.",
  ui_story_30960601_34_dialog_content = "Menolak dengan sopan.",
  ui_story_30960601_35_dialog_content = "Oh, aku mengerti... Pertanyaan ini untuk mengetahui apakah aku bisa mengambil inisiatif untuk menghindari potensi konflik, 'kan?",
  ui_story_30960601_36_dialog_content = "Tentu saja aku akan memilih untuk menolak dengan sopan setelah mengucapkan terima kasih!",
  ui_story_30960601_37_dialog_content = "Benar. Kamu cukup tanggap, ya?",
  ui_story_30960601_38_dialog_content = "Menolaknya dengan kasar.",
  ui_story_30960601_39_dialog_content = "Yah, suatu kali pernah ada orang yang mengajakku untuk menjadi Eclipsite... Itu seperti ajakan untuk bergabung dengan timnya.",
  ui_story_30960601_40_dialog_content = "Setelah itu, aku menolaknya dengan sangat kasar... Lalu aku mengalahkannya dalam pertempuran.",
  ui_story_30960601_41_dialog_content = "Yah, mengingat situasinya... kurasa ada alasan di balik pilihan dari tindakan itu, 'kan?",
  ui_story_30960601_42_dialog_content = "Sekarang, pertanyaan berikutnya...",
  ui_story_30960601_43_dialog_content = "Jika ada orang yang mengambil barangmu dan tidak mau mengembalikannya, apa yang akan kamu lakukan?",
  ui_story_30960601_44_dialog_content = "A: Dengan sopan memintanya memberi penjelasan...",
  ui_story_30960601_45_dialog_content = "Oh! Memang pernah ada orang yang mencuri komponen milik kaum Caelestite sebelumnya...",
  ui_story_30960601_46_dialog_content = "Meskipun itu bukan barang pribadiku, aku tak mau menyerahkannya pada orang itu.",
  ui_story_30960601_47_dialog_content = "Jadi, aku memilih B! \"Mengalahkannya, dan merebut kembali komponen itu!\"",
  ui_story_30960601_48_dialog_content = "Wah... Jawabanmu agak mengejutkan. Sebentar, biar kuperiksa dulu pamfletku...",
  ui_story_30960601_49_dialog_content = "Ehem, bagus sekali. Apa menurutmu pilihanmu sudah tepat?",
  ui_story_30960601_50_dialog_content = "Tidak... Keadaan tak pernah sesederhana yang kita semua pikirkan.",
  ui_story_30960601_51_dialog_content = "<size=45>Tak pernah sesederhana itu!</size>",
  ui_story_30960601_52_dialog_content = "K-kenapa kamu jadi menaikkan nada bicaramu dan mengucapkannya dua kali?",
  ui_story_30960601_53_dialog_content = "Karena seperti itulah arahan di pamflet.",
  ui_story_30960601_54_dialog_content = "Oh, sebentar... Menurut pamflet, sesekali kita harus memutar iklan selama pelajaran. Aku hampir lupa!",
  ui_story_30960601_55_dialog_content = "Hah? Memutar apa...?",
  ui_story_30960601_56_dialog_content = "\"Masih terjebak dalam kehidupan yang gagal?\"",
  ui_story_30960601_57_dialog_content = "\"Masih memutar otak untuk mencari cara meningkatkan diri?\"",
  ui_story_30960601_58_dialog_content = "\"Keberhasilan bukanlah metode atau keadaan, tapi pola pikir!\"",
  ui_story_30960601_59_dialog_content = "\"Jalani hidup yang lebih baik dengan panduan kursus spesial kami!\"",
  ui_story_30960601_60_dialog_content = "\"Bertindaklah sekarang, dan dapatkan diskon 20% untuk semua kursus dengan mengajak temanmu untuk ikut mendaftar!\"",
  ui_story_30960601_61_dialog_content = "...",
  ui_story_30960601_62_dialog_content = "Mau mendaftar?",
  ui_story_30960601_63_dialog_content = "Aku mau mendaftar untuk lima pelajaran lagi!",
  ui_story_30960601_64_dialog_content = "Kalau ini demi ilmu pengetahuan, aku tak keberatan untuk mengeluarkan lebih banyak biaya.",
  ui_story_30960601_65_dialog_content = "Aku yakin Vice juga akan memahaminya!",
  ui_story_30960601_66_dialog_content = "Terima kasih atas dukunganmu! Ini sangat membantu!",
  ui_story_30960601_67_dialog_content = "\"Membantu\"? Apa maksudmu?",
  ui_story_30960601_68_dialog_content = "Eh, b-bukan apa-apa, kok! Omong-omong, sebaiknya kita lanjutkan pelajarannya...",
  ui_story_30960601_69_dialog_content = "Tidak perlu.",
  ui_story_30960601_70_dialog_content = "Belakangan ini aku sedang agak bokek...",
  ui_story_30960601_71_dialog_content = "Tapi, bukankah kamu Navigator yang terkenal?",
  ui_story_30960601_72_dialog_content = "Kamu punya kenalan, dan Colossus! Uang pasti bukan masalah bagimu...",
  ui_story_30960601_73_dialog_content = "Yah, membuat Colossus tetap mengudara dan memastikan semua orang merasa nyaman dan gembira juga butuh biaya...",
  ui_story_30960601_74_dialog_content = "Aku tidak boleh mengeluarkan lebih banyak uang, jadi ayo kita lanjutkan saja pelajarannya.",
  ui_story_30960601_75_dialog_content = "Baiklah. Aku tak akan memaksamu untuk mengeluarkan lebih banyak uang kalau kamu tidak mau... Nah, ayo kita lanjutkan...",
  ui_story_30960601_76_dialog_content = "Ada berbagai jenis \"konflik\". Aku akan mengilustrasikannya dengan sebuah gambar.",
  ui_story_30960601_77_dialog_content = "Dan... sebuah gambar lain...",
  ui_story_30960601_78_dialog_content = "Dan satu lagi... Dan satu lagi...",
  ui_story_30960601_79_dialog_content = "Anu... Sariel? Berapa banyak lagi gambar yang akan kamu buat?",
  ui_story_30960601_80_dialog_content = "Sebentar! Aku mau menggambar satu lagi agar simetris!",
  ui_story_30960601_81_dialog_content = "Oh, aku benar-benar lupa kalau kamu suka yang serba simetris...",
  ui_story_30960601_82_dialog_content = "Nah, karena kita sedang membicarakannya... Hanya kaus kaki kananmu yang berlubang.",
  ui_story_30960601_83_dialog_content = "Apa?!",
  ui_story_30960601_84_dialog_content = "Sebentar, biar kulubangi yang kiri...",
  ui_story_30960601_85_dialog_content = "Selain itu, ini disebut \"stoking\", bukan kaus kaki...",
  ui_story_30960601_86_dialog_content = "Sebutannya tidaklah penting, yang lebih mengkhawatirkan...",
  ui_story_30960601_87_dialog_content = "Adalah aku tak pernah mengira kamu bakal merusak pakaianmu hanya agar membuatnya simetris.",
  ui_story_30960601_88_dialog_content = "Tapi, kamu kan tahu kalau hal-hal yang tidak simetris membuatku sangat terganggu!",
  ui_story_30960601_89_dialog_content = "Omong-omong, kenapa kamu sangat mempermasalahkan kesimetrisan? Yang seperti ini sedikit berlebihan, tahu...",
  ui_story_30960601_90_dialog_content = "Itu karena simetri menandakan keseimbangan dan stabilitas! Kehormatan dan keindahan!",
  ui_story_30960601_91_dialog_content = "Aku menyebut keindahan ini sebagai \"estetika simetri\".",
  ui_story_30960601_92_dialog_content = "Tahu tidak?",
  ui_story_30960601_93_dialog_content = "Sisi kiri wajah kita tidak 100% simetris dengan yang kanan.",
  ui_story_30960601_94_dialog_content = "Tapi, saat becermin, kita cenderung mengabaikannya.",
  ui_story_30960601_95_dialog_content = "Ini karena kita terlahir dengan keinginan bawaan untuk hal-hal yang simetris...",
  ui_story_30960601_96_dialog_content = "Bukankah itu karena perbedaannya terlalu kecil sampai-sampai luput dari pengamatan?",
  ui_story_30960601_97_dialog_content = "Hah? Kamu benar-benar meragukan penelitian \"estetika simetri\"-ku?",
  ui_story_30960601_98_dialog_content = "Eh... Lupakan saja perkataanku tadi. Omong-omong... Apa berarti tanduk di kepalamu juga tidak simetris?",
  ui_story_30960601_99_dialog_content = "Ah! J-jangan singgung tandukku! Melupakannya saja sudah cukup sulit!",
  ui_story_30960601_100_dialog_content = "Ayo kita kembali ke pelajaran saja!",
  ui_story_30960601_101_dialog_content = "Baiklah... Tolong jelaskan lebih lanjut tentang gambar yang kamu buat barusan, ya?",
  ui_story_30960601_102_dialog_content = "Coba kulihat dulu isi pamfletnya...",
  ui_story_30960601_103_dialog_content = "Sepertinya kamu tidak menguasai materi kursusnya... Apa kamu benar-benar bisa mengajar dengan cara begitu?",
  ui_story_30960601_104_dialog_content = "Maaf, kepala Rising Star Agency memberiku materinya secara mendadak, jadi aku juga kesulitan memahaminya.",
  ui_story_30960601_105_dialog_content = "Kelihatannya sangat tak bisa diandalkan...",
  ui_story_30960601_107_dialog_content = "Grrr... Kenapa huruf-huruf ini tidak ada yang selaras satu sama lain?",
  ui_story_30960601_108_dialog_content = "Hah?",
  ui_story_30960601_109_dialog_content = "Di pamflet ini. Lihat, 'kan? Beberapa baris terakhir benar-benar tidak selaras!",
  ui_story_30960601_110_dialog_content = "\"'Cara Menghindari Konflik dengan Orang Lain', Subbagian 2:\"",
  ui_story_30960601_111_dialog_content = "\"Setelah pertanyaan sesi pertama, kita bisa menentukan bentuk komunikasi yang positif dengan pelanggan.\"",
  ui_story_30960601_112_dialog_content = "\"Sekarang, ini adalah kesempatan terbaik untuk menjelaskan filosofi pemasaran kita!\"",
  ui_story_30960601_113_dialog_content = "Huruf-hurufnya tidak selaras, sangat menjengkelkan!",
  ui_story_30960601_114_dialog_content = "Kurasa isi pamflet ini jauh lebih mengkhawatirkan dari hurufnya, Sariel!",
  ui_story_30960601_115_dialog_content = "Soroz mengajariku selama tujuh belas tahun... Aku berani jamin bukan begini pelajaran seharusnya diberikan.",
  ui_story_30960601_116_dialog_content = "Kelas adalah ruangan untuk berbagi dan menerima ilmu pengetahuan.",
  ui_story_30960601_117_dialog_content = "Memang benar, pelajaran di sini juga sangat berbeda dengan yang kuikuti dulu... Tapi, mungkin ini hanya pengajaran dengan metode terbaru?",
  ui_story_30960601_118_dialog_content = "Mereka bahkan juga memberi kami pelatihan...",
  ui_story_30960601_119_dialog_content = "Apa yang mereka ajarkan?",
  ui_story_30960601_120_dialog_content = "Yah, mereka menunjukkan cara memperkenalkan diri dan kurikulum kami...",
  ui_story_30960601_121_dialog_content = "Dan cara mendorong pelanggan kami agar tetap mengikuti pelajaran... Dan cara <color=#FFB400>mempromosikan lebih banyak pelajaran untuk mereka</color>...",
  ui_story_30960601_122_dialog_content = "Ini saja sudah terdengar sangat mencurigakan!",
  ui_story_30960601_123_dialog_content = "Kalau kamu punya pertanyaan, komentar, atau masalah, silakan isi formulir ini.",
  ui_story_30960601_124_dialog_content = "Selain itu, jangan lupa menilai pengalaman belajar denganku hari ini dengan keterangan \"Sangat Memuaskan\"!",
  ui_story_30960601_125_dialog_content = "Tapi, kenapa? Aku kan sama sekali tidak puas...",
  ui_story_30960601_126_dialog_content = "Karena hanya dengan begitulah aku akan bisa mendapat bonus penuh dari pekerjaanku.",
  ui_story_30960601_127_dialog_content = "Kalau tidak, mereka akan memotong gajiku.",
  ui_story_30960601_128_dialog_content = "Aku bokek, dan butuh bonusnya untuk bertahan hidup.",
  ui_story_30960601_129_dialog_content = "Kalau mereka memotong gajiku...",
  ui_story_30960601_130_dialog_content = "Bagaimana aku bisa membeli makanan untukku atau kucingku...?",
  ui_story_30960601_131_dialog_content = "J-jangan cemas, aku akan menilai pelajaran ini dengan keterangan \"Sangat Memuaskan\"!",
  ui_story_30960601_132_dialog_content = "Tapi, bukankah agak keterlaluan kalau mereka memotong gajimu gara-gara nilaimu tidak sebaik itu?",
  ui_story_30960601_133_dialog_content = "Belum lagi... poin-poin yang meragukan itu.",
  ui_story_30960601_134_dialog_content = "Sudah pasti ada yang tidak beres dengan Rising Star Agency ini!",
  ui_story_30960601_135_dialog_content = "Misalnya?",
  ui_story_30960601_136_dialog_content = "Sebentar, aku akan menanyakan masalah ini kepada beberapa \"ahli pemasaran\"...",
  ui_story_30960601_137_dialog_content = "Ini sih penipuan. Iya, 'kan?",
  ui_story_30960601_138_dialog_content = "Sudah pasti penipuan.",
  ui_story_30960601_139_dialog_content = "Mereka menipumu agar mau bekerja untuk agensi yang mencurigakan ini.",
  ui_story_30960601_140_dialog_content = "Hanya dengan melihatnya saja aku yakin ini adalah <color=#FFB400>skema pemasaran multilevel</color>. Bisnis yang jujur tak akan melakukan hal semacam ini.",
  ui_story_30960601_143_dialog_content = "T-tapi, aku sudah menandatangani kontrak dengan Rising Star Agency, dan membayar setoran...",
  ui_story_30960601_144_dialog_content = "*Menghela napas* Jangan bekerja di tempat yang mencurigakan seperti ini lagi!",
  ui_story_30960601_145_dialog_content = "Ada bermacam-macam bisnis di Umbraton; ada yang jujur, ada yang tidak.",
  ui_story_30960601_146_dialog_content = "Kalau mencari pekerjaan, kamu harus mencari tahu dulu mana saja kantor yang tepercaya dengan latar belakang dan sejarah yang solid.",
  ui_story_30960601_147_dialog_content = "Aku akan meminta Guild untuk memeriksa \"Rising Star Agency\".",
  ui_story_30960601_148_dialog_content = "Kalau ada dokumen yang sudah kamu tanda tangani, sebaiknya perlihatkan padaku. Biar kuperiksa.",
  ui_story_30960601_149_dialog_content = "Aku yakin dokumen itu mencakup syarat dan ketentuan yang bisa menjebak orang-orang yang lengah.",
  ui_story_30960601_150_dialog_content = "Terima kasih... Terima kasih banyak.",
  ui_story_30960601_151_dialog_content = "Kalau agensi itu memang menipuku, berarti uang yang sudah kubayarkan...",
  ui_story_30960601_152_dialog_content = "Sia-sia saja, 'kan?!",
  ui_story_30960601_153_dialog_content = "1.998 Nightium... Seluruh uang yang sudah kudapatkan dengan susah payah...",
  ui_story_30960601_154_dialog_content = "Tadinya aku hanya ingin mempelajari ilmu pengetahuan baru dan berharga. Tapi, tak kusangka...",
  ui_story_30960601_155_dialog_content = "Jangan khawatir, PlayerName. Aku akan menyelesaikan pelajarannya.",
  ui_story_30960601_156_dialog_content = "Mereka memang memberi kami pamflet, tapi aku juga punya materi kursus sendiri.",
  ui_story_30960601_157_dialog_content = "Aku sudah banyak membaca buku agar siap dengan situasi seperti ini. Lihat, aku juga punya buku catatan sendiri!",
  ui_story_30960601_158_dialog_content = "Sariel, kamu...",
  ui_story_30960601_159_dialog_content = "Lihat! Setiap barisnya sangat selaras!",
  ui_story_30960601_160_dialog_content = "Apa intinya benar-benar itu...?",
  ui_story_30960601_161_dialog_content = "Omong-omong, aku sudah muak mengikuti pamflet mereka... Bagaimana? Masih berminat mengikuti pelajaranku?",
  ui_story_30960601_162_dialog_content = "Tentu saja!",
  ui_story_30960601_163_dialog_content = "Bagus, ayo kita mulai dari awal.",
  ui_story_30960601_164_dialog_content = "Nah, untuk memahami \"konflik\", kita harus memahami definisinya dulu.",
  ui_story_30960601_165_dialog_content = "\"Definisi konflik terutama menekankan pada keberadaan dan kesadaran akan perbedaan kepentingan…\"",
  ui_story_30960601_167_dialog_content = "Waktu kita masih banyak, jadi aku pasti akan menguraikan semua poin ini dengan cermat.",
  ui_story_30960601_168_dialog_content = "Bagus! Seperti pelajaran sungguhan!",
  ui_story_30960601_169_dialog_content = "Haha, kamu memang murid yang patuh, PlayerName...",
  ui_story_30960602_1_dialog_content = "Saya punya kabar baik, PlayerName!",
  ui_story_30960602_2_dialog_content = "Aku seharusnya bisa membayar kembali karena kamu telah membelikan aku makan siang beberapa hari yang lalu!",
  ui_story_30960602_3_option_content = "Jangan khawatir, itu traktiran dariku...",
  ui_story_30960602_4_dialog_content = "Itu tidak bisa. Dulu Kakek selalu bilang bahwa bahkan antar saudara perempuan sekalipun harus saling membayar setelah meminjam uang.",
  ui_story_30960602_5_dialog_content = "Lagi pula, ada seseorang yang menawarkan pekerjaan super menguntungkan kepada saya!",
  ui_story_30960602_6_option_content = "Apakah Lady Sheol menawarkan pekerjaan baru kepada Anda?",
  ui_story_30960602_7_dialog_content = "Ini pekerjaan baru, tapi bukan dari dia.",
  ui_story_30960602_8_dialog_content = "Lokasinya juga tampak benar-benar kelas atas.",
  ui_story_30960602_9_dialog_content = "Jadi, apa saja persisnya yang menjadi tugas dalam pekerjaan ini?",
  ui_story_30960602_10_dialog_content = "Saya diberitahu bahwa bahkan orang ceroboh seperti saya seharusnya bisa mengatasinya.",
  ui_story_30960602_11_dialog_content = "Yang perlu saya lakukan hanyalah duduk di meja dan bermain sepanjang hari.",
  ui_story_30960602_12_dialog_content = "Main?",
  ui_story_30960602_13_dialog_content = "Yep! Ini salah satu permainan di mana mereka melempar bola kecil ke roda berputar yang memiliki banyak angka di atasnya.",
  ui_story_30960602_14_dialog_content = "... Maksudmu seperti roulette?",
  ui_story_30960602_15_dialog_content = "Aku tidak yakin, tapi meskipun aku sering mengacaukan sesuatu, bermain adalah hal yang selalu aku kuasai!",
  ui_story_30960602_16_dialog_content = "Tunggu, jadi kamu setuju untuk melakukan ini tanpa tahu permainannya?",
  ui_story_30960602_17_dialog_content = "Kamu yakin kamu tidak ditipu atau semacamnya? Banyak penipu yang muncul menjelang tahun baru...",
  ui_story_30960602_18_dialog_content = "Tidak mungkin! Lagipula, saya sudah ditipu bulan lalu; apa peluangnya terjadi dua kali dalam dua bulan?",
  ui_story_30960602_19_dialog_content = "Kurasa aku harus ikut denganmu, demi keamanan...",
  ui_story_30960602_20_dialog_content = "Aku khawatir kali ini kamu bisa terlibat masalah yang serius.",
  ui_story_30960602_21_dialog_content = "Kamu tidak merasa meremehkanku?",
  ui_story_30960602_22_dialog_content = "Namun, aku tidak keberatan jika kamu ikut. Toh, Bos bilang aku dibayar per hari.",
  ui_story_30960602_23_dialog_content = "Setelah saya mencairkan gaji saya, saya akan bisa membayar Anda kembali dan mentraktir Anda makan enak. Bahkan akan ada ayam!",
  ui_story_30960602_24_dialog_content = "<color=#e8d9bb>Keesokan harinya, setelah tiba di lokasi yang ditentukan Sariel.</color>",
  ui_story_30960602_25_dialog_content = "...",
  ui_story_30960602_26_dialog_content = "Hai, PlayerName!",
  ui_story_30960602_27_dialog_content = "Apa dengan pakaian itu...?",
  ui_story_30960602_28_dialog_content = "Bos memberikannya kepada saya dan mengatakan itu akan membuat saya tidak terlalu menonjol.",
  ui_story_30960602_29_dialog_content = "A-Aku mengerti... Mereka memang memiliki suasana bawah tanah tertentu.",
  ui_story_30960602_30_dialog_content = "(Pakaian yang tak bisa dipercaya...)",
  ui_story_30960602_31_dialog_content = "Tapi... aku benar-benar... tidak tahan dengan mereka...",
  ui_story_30960602_32_dialog_content = "<color=#e8d9bb>Sariel menderita gangguan obsesif-kompulsif, terutama saat menyangkut objek yang tidak simetris.</color>",
  ui_story_30960602_33_dialog_content = "<color=#e8d9bb>Kondisinya sangat serius sehingga jika ada sobekan di satu stoking, dia akan merobek lubang di stoking lainnya agar cocok.</color>",
  ui_story_30960602_34_dialog_content = "<color=#e8d9bb>Saya harus mengatakan, pakaian yang dia kenakan sekarang ini benar-benar menyoroti semua kekurangannya—</color>",
  ui_story_30960602_35_dialog_content = "<color=#e8d9bb>Aksesoris rambut yang tidak simetris.</color>",
  ui_story_30960602_36_dialog_content = "<color=#e8d9bb>Sebuah gaun asimetris.</color>",
  ui_story_30960602_37_dialog_content = "<color=#e8d9bb>Dan stoking yang tidak simetris.</color>",
  ui_story_30960602_38_dialog_content = "Huu-huu...",
  ui_story_30960602_39_dialog_content = "(Dia nggak benar-benar akan menangis, kan...?)",
  ui_story_30960602_40_dialog_content = "Uh, Sariel? Apakah kamu sudah membahas ini dengan penipu itu... eh, maksudku, bosmu?",
  ui_story_30960602_41_dialog_content = "Aku sih... tapi bos bilang...",
  ui_story_30960602_42_dialog_content = "Kamu sungguh mengeluhkan pakaian gratis yang kuberikan? Sungguh sombong.",
  ui_story_30960602_43_dialog_content = "Apakah hidup di Umbraton selama bertahun-tahun membuatmu kehilangan akal sehat?",
  ui_story_30960602_44_dialog_content = "Banyak orang yang memohon untuk mendapatkan pekerjaan manis seperti ini. Jika kamu tidak menginginkannya, saya yakin ada orang lain yang akan mengambilnya!",
  ui_story_30960602_45_dialog_content = "Serius, lihatlah dirimu sendiri! Setelah bertahun-tahun, apakah kekayaan bersihmu benar-benar bertambah? Bisakah kau benar-benar mengatakan bahwa kau telah bekerja keras sama sekali?",
  ui_story_30960602_46_dialog_content = "Bagaimana kamu mengharapkan untuk menghasilkan uang jika kamu rela menyerah hanya karena sesuatu yang begitu sepele?",
  ui_story_30960602_47_dialog_content = "... Itu saja.",
  ui_story_30960602_48_dialog_content = "Itu jauh melampaui batas!",
  ui_story_30960602_49_dialog_content = "Dia juga bilang aku tidak akan dibayar jika tidak memakai pakaian ini dan aku harus menggantinya jika mereka robek.",
  ui_story_30960602_50_dialog_content = "Jadi, meskipun segalanya, kamu masih ingin melakukan pekerjaan ini?",
  ui_story_30960602_51_dialog_content = "… Aku…",
  ui_story_30960602_52_dialog_content = "... Aku punya alasan untuk menghasilkan uang, jadi saya ingin mencobanya.",
  ui_story_30960602_53_dialog_content = "Terima kasih sudah menemaniku, btw. Dengan kamu di sini... Aku rasa aku bisa mengatasinya sedikit lebih baik...",
  ui_story_30960602_54_dialog_content = "Sariel...",
  ui_story_30960602_55_dialog_content = "(Awalnya aku hanya ingin memastikan dia tidak tertipu, tapi sekarang aku merasa terdorong untuk membantunya menyelesaikan pekerjaannya.)",
  ui_story_30960602_56_dialog_content = "Jangan khawatir, aku akan membantumu semampu yang aku bisa.",
  ui_story_30960602_57_dialog_content = "Boo-hoo... Aku sangat berterima kasih! Tak bisa kubayangkan apa yang akan terjadi padaku tanpa kamu di sini!",
  ui_story_30960602_58_dialog_content = "Haha, nggak usah disebutkan. Sebentar lagi waktunya absen masuk, kan? Ayo kita berangkat.",
  ui_story_30960602_59_dialog_content = "<color=#e8d9bb>Di rumah permainan bawah tanah.</color>",
  ui_story_30960602_60_dialog_content = "<color=#e8d9bb>Suara roda berputar dan dadu bergulir terdengar di seluruh tempat, sementara orang-orang menatap dengan saksama kartu yang dibalik di meja mereka.</color>",
  ui_story_30960602_61_dialog_content = "<color=#e8d9bb>Kerumunan di sekitar meja bersorak dan mengeluh saat permainan terus berlangsung.</color>",
  ui_story_30960602_62_dialog_content = "(Aku rasa aku tidak cocok di tempat seperti ini...)",
  ui_story_30960602_63_dialog_content = "(Tapi ini untuk Sariel, jadi aku harus menahan sakit dan tetap melakukannya!)",
  ui_story_30960602_64_dialog_content = "Jadi, bos kamu juga di sini, Sariel?",
  ui_story_30960602_65_dialog_content = "Ya, aku baru saja melihatnya beberapa detik yang lalu. Dia tepat di... Hah? Kemana dia pergi?",
  ui_story_30960602_66_dialog_content = "Kurasa tidak masalah. Dia memberiku penerima kecil ini untuk ditaruh di telingaku, yang bisa kugunakan untuk menghubunginya kapanpun aku butuh. Oh, dia sedang memanggilku sekarang!",
  ui_story_30960602_67_dialog_content = "Orang di sebelahku? Maksudmu PlayerName? Dia di sini untuk membantuku... Maksudku, dia hanya teman.",
  ui_story_30960602_68_dialog_content = "Oke, jadi pertama-tama aku harus menukar uang yang kamu berikan tadi dengan token, lalu duduk di salah satu meja itu...",
  ui_story_30960602_69_dialog_content = "Setelah itu, aku tinggal memilih angka... dan menyerahkan token-tokenku...",
  ui_story_30960602_70_dialog_content = "T-Tunggu, kamu menawarkan semua tokenmu?!",
  ui_story_30960602_71_dialog_content = "Oh, itu hal yang buruk?",
  ui_story_30960602_72_dialog_content = "Kamu tidak seharusnya all-in di permainan pertamamu!",
  ui_story_30960602_73_dialog_content = "Tiga puluh tujuh, hitam. Selamat, Nona, kamu menang.",
  ui_story_30960602_74_dialog_content = "Tapi dia bilang aku menang! Dan lihat, dia memberiku banyak token!",
  ui_story_30960602_75_dialog_content = "Bagaimana tepatnya aku menang? Apakah karena aku menawarkan token terbanyak?",
  ui_story_30960602_76_dialog_content = "Keberuntungan pemula, saya kira... Pokoknya, jangan all-in seperti itu lagi. Mulailah dengan satu atau dua token dan lanjutkan dari situ.",
  ui_story_30960602_77_dialog_content = "Baiklah, kamu bosnya. Lagipula, sepertinya kamu lebih tahu tentang ini daripada saya.",
  ui_story_30960602_78_dialog_content = "Aku juga kurang mengerti, tapi salah satu temanku pernah mengajari beberapa trik sebelumnya.",
  ui_story_30960602_79_dialog_content = "(Meskipun saya hanya mempelajari hal ini untuk menghindari penipuan, sepertinya akhirnya saya bisa menggunakannya untuk kebaikan...)",
  ui_story_30960602_80_dialog_content = "Jadi, apa sebenarnya maksud dari \"all-in\"?",
  ui_story_30960602_81_dialog_content = "...",
  ui_story_30960602_82_dialog_content = "Dua, merah. Selamat, Nona, kamu menang.",
  ui_story_30960602_83_dialog_content = "Sulit dipercaya...",
  ui_story_30960602_84_dialog_content = "Dua puluh lima kemenangan berturut-turut! Gadis ini pasti adalah Dewi Fortuna sendiri!",
  ui_story_30960602_85_dialog_content = "Kita juga harus berada di levelnya!",
  ui_story_30960602_86_dialog_content = "Uh, PlayerName? Kenapa semua orang menatapku?",
  ui_story_30960602_87_dialog_content = "Permainan ini tidak terlalu sulit. Selama kamu menawarkan jumlah token genap, kamu selalu menang.",
  ui_story_30960602_88_dialog_content = "Kalau aku jadi kamu, aku akan pelankan suara. Kita bakal masalah kalau orang-orang itu dengar kamu setelah kalah berkali-kali.",
  ui_story_30960602_89_dialog_content = "Memang terasa cukup aneh sih. Kamu sudah menang dua puluh lima kali... Dan hanya dengan bertaruh pada angka tunggal, tidak kurang.",
  ui_story_30960602_90_dialog_content = "Meskipun dengan keberuntungan yang luar biasa, ini tampaknya terlalu mustahil. Mungkin rumah permainan ini menggunakan kamu sebagai umpan?",
  ui_story_30960602_91_dialog_content = "Apa maksudmu, \"tukang giring\"?",
  ui_story_30960602_92_dialog_content = "... Tidak apa-apa. Lama sekali kalau harus menjelaskan.",
  ui_story_30960602_93_dialog_content = "Pokoknya, aku hampir tidak bisa memegang semua token ini... Aku rasa cukup untuk saat ini.",
  ui_story_30960602_94_dialog_content = "Hah? Bos lagi...",
  ui_story_30960602_95_dialog_content = "Apa itu? Kamu ingin aku terus bermain atau aku tidak akan dibayar? Tapi kenapa...?",
  ui_story_30960602_96_dialog_content = "Bosmu ingin kamu terus melanjutkan?",
  ui_story_30960602_97_dialog_content = "Yah, memang bukan hal yang paling jujur untuk dilakukan, tapi jika itu yang dia inginkan darimu... Kurasa tidak apa-apa.",
  ui_story_30960602_98_dialog_content = "Jadi apa maksud dari semua ini? Aku mulai merasa bosan... Dan pakaian ini membuatku kesal...",
  ui_story_30960602_99_dialog_content = "Yaaawn—<size=45>Wah!</size>",
  ui_story_30960602_100_dialog_content = "Sariel menabrak tumpukan token-nya saat meregangkan punggung, tetapi berhasil menghindari menjatuhkannya dengan berputar menjauh.",
  ui_story_30960602_101_dialog_content = "Sayangnya, gerakan canggung itu membuatnya menendang kursinya dan menabrak meja.",
  ui_story_30960602_102_dialog_content = "Butuh keterampilan tertentu untuk jatuh dengan cara yang spektakuler seperti itu.",
  ui_story_30960602_103_dialog_content = "Aduh...",
  ui_story_30960602_104_dialog_content = "... Kamu baik-baik saja? Tadi kamu terluka?",
  ui_story_30960602_105_dialog_content = "Aku... Aku rasa aku keseleo otot punggung... Rasanya sakit sekali...",
  ui_story_30960602_106_dialog_content = "Tunggu, rasanya ada sesuatu yang menusuk dari bawah punggungku.",
  ui_story_30960602_107_dialog_content = "Bisakah kamu membantu menariknya? Aku tidak bisa mencapainya...",
  ui_story_30960602_108_dialog_content = "... Di bawah punggungmu? Aku akan mencoba...",
  ui_story_30960602_109_dialog_content = "Ahh...",
  ui_story_30960602_110_dialog_content = "Ada apa?",
  ui_story_30960602_111_dialog_content = "Tidak apa-apa, rasanya jauh lebih baik saat kamu menggosok punggungku di tempat itu...",
  ui_story_30960602_112_dialog_content = "Uh, jadi di mana benda yang mencolek kamu ini?",
  ui_story_30960602_113_dialog_content = "... Oh, benar... Saya rasa sedikit lebih rendah.",
  ui_story_30960602_114_dialog_content = "... Uh... Aku tidak merasakan apa-apa di sana bawah.",
  ui_story_30960602_115_dialog_content = "Tidak, sedikit lebih rendah...",
  ui_story_30960602_116_dialog_content = "Lebih rendah...",
  ui_story_30960602_117_dialog_content = "Ah, itu ada... Hah? Apa ini?",
  ui_story_30960602_118_dialog_content = "<size=45>Itu milikku! Kembalikan!</size>",
  ui_story_30960602_119_dialog_content = "Seorang pria tua merebut benda itu sebelum siapa pun bisa melihatnya dengan jelas.",
  ui_story_30960602_120_dialog_content = "Tunggu... Bukankah kamu salah satu pemain di meja kita? Maaf, tapi apa itu...",
  ui_story_30960602_121_dialog_content = "<size=45>Hentikan pria itu!</size>",
  ui_story_30960602_122_dialog_content = "Dia memiliki alat curang di tangannya!",
  ui_story_30960602_123_dialog_content = "Apa? ... Hei, dia mencoba melarikan diri!",
  ui_story_30960602_124_dialog_content = "<size=45>Setelah dia!</size>",
  ui_story_30960602_125_dialog_content = "<size=45>Blokir pintu keluar! Jangan biarkan dia kabur!</size>",
  ui_story_30960602_126_dialog_content = "<color=#e8d9bb>Berkat respons yang sangat cepat, para karyawan dengan sigap menangkap pria tua yang curang itu.</color>",
  ui_story_30960602_127_dialog_content = "<color=#e8d9bb>Tak lama kemudian, semua kemenangan dan kekalahan di meja itu menjadi tidak valid.</color>",
  ui_story_30960602_128_dialog_content = "<color=#e8d9bb>Dengan kata lain, waktu dan usaha yang Sariel dan aku habiskan di sini semua sia-sia.</color>",
  ui_story_30960602_129_dialog_content = "Saya harus bilang, ini sama sekali bukan bagaimana saya mengharapkan semuanya berakhir.",
  ui_story_30960602_130_dialog_content = "Hilang semua gajiku... huu-huu...",
  ui_story_30960602_131_option_content = "Syukurlah kamu tidak mendapat masalah.",
  ui_story_30960602_132_option_content = "Setidaknya kamu membantu menangkap seorang penipu.",
  ui_story_30960602_133_dialog_content = "Aku tidak percaya orang yang merekrut kamu malah memanfaatkanmu seperti ini untuk menipu dan mendapatkan keuntungan.",
  ui_story_30960602_134_dialog_content = "Lagi pula, kamu mungkin tidak mengerti apa pun yang baru saja aku katakan...",
  ui_story_30960602_135_dialog_content = "Mengapa dia menggunakan saya untuk menipu daripada melakukannya sendiri?",
  ui_story_30960602_136_dialog_content = "Saya pikir dia menggunakan kamu untuk mengalihkan perhatian dari dirinya sendiri. Dengan membuatmu terlihat seperti Dewi Fortuna, dia akan terus bermain tanpa menimbulkan kecurigaan yang berlebihan.",
  ui_story_30960602_137_dialog_content = "Aku yakin pakaian yang dia berikan padamu juga bertujuan untuk mengalihkan perhatian orang darinya.",
  ui_story_30960602_138_dialog_content = "Begitu... Tapi, aku masih belum mengerti.",
  ui_story_30960602_139_dialog_content = "Jadi, apa yang harus kulakukan tentang pakaian ini?",
  ui_story_30960602_140_dialog_content = "Tidak tahu. Menurutmu, apakah kita harus mengembalikannya kepadanya meskipun dia sudah ditangkap?",
  ui_story_30960602_141_dialog_content = "Tidak mungkin. Jika saya melakukan itu, saya benar-benar akan berakhir tanpa hasil dari pekerjaan ini.",
  ui_story_30960602_142_dialog_content = "Selain itu... Sudah saatnya saya melatih diri untuk mengatasi situasi yang sulit...",
  ui_story_30960602_143_dialog_content = "Apa maksudmu?",
  ui_story_30960602_144_dialog_content = "Aku menghabiskan satu hari penuh mengenakan pakaian yang buruk ini, tapi setiap kali mulai merasa tidak nyaman... aku jadi teringat kamu.",
  ui_story_30960602_145_dialog_content = "Kamu... memikirkanku?",
  ui_story_30960602_146_dialog_content = "Ya. Saya memikirkan apa yang kamu katakan padaku, dan bagaimana kamu ada di sana untuk membantuku.",
  ui_story_30960602_147_dialog_content = "... Setelah itu... Aku tidak merasa terlalu tidak nyaman.",
  ui_story_30960602_148_dialog_content = "...",
  ui_story_30960602_149_dialog_content = "S-Seperti... Ketika kamu menggosok punggungku. Rasanya sama nyamannya.",
  ui_story_30960602_150_dialog_content = "Itu dua hal yang benar-benar berbeda! Dan kenapa kamu harus mengatakannya seperti itu...?",
  ui_story_30960602_151_dialog_content = "Omong-omong, aku ingin melatih diri untuk mentolerir hal-hal asimetris dengan memakai pakaian ini lagi... Maukah kamu membantuku?",
  ui_story_30960602_152_dialog_content = "(Sariel selalu terlihat malas, tapi...)",
  ui_story_30960602_153_dialog_content = "(... Tapi, sepertinya dia juga punya hari-hari serius, ya.)",
  ui_story_30960602_154_dialog_content = "Tentu, saya akan dengan senang hati membantu!",
  ui_story_30960602_155_dialog_content = "Kenakan apa pun yang kamu inginkan, dan aku akan membantu kamu berlatih selama yang kamu butuhkan!",
  ui_story_30960602_156_dialog_content = "Heehee, terima kasih! Kamu benar-benar orang terhebat yang pernah aku temui dalam hidupku.",
  ui_story_30960602_157_dialog_content = "Sepertinya hari ini ternyata tidak sepenuhnya gagal.",
  ui_story_30960602_158_dialog_content = "... Yang mengingatkan saya, Lady Sheol bilang untuk makan malam ayam setelah keluar dari rumah permainan.",
  ui_story_30960602_159_dialog_content = "Kamu punya uang?",
  ui_story_30960602_160_dialog_content = "Aku tidak...",
  ui_story_30960602_161_dialog_content = "Tidak apa-apa, hari ini aku yang traktir.",
  ui_story_30960602_162_dialog_content = "Benarkah?!",
  ui_story_30960602_163_dialog_content = "Kamu benar-benar yang terbaik, PlayerName!"
}
return config
